);
import React, { useEffect } from "react";
import { OnloadArgs } from "roamjs-components/types";
import getDiscourseNodes, {
  excludeDefaultNodes,
} from "~/utils/getDiscourseNodes";
import { nodeConfigSegmentIds } from "./utils/settingsNavigation";
import { useSettingsNav } from "./navigation/SettingsNavContext";
import SettingsPageHeader from "./navigation/SettingsPageHeader";
import DiscourseNodeConfigPanel from "./DiscourseNodeConfigPanel";
import NodeConfig from "./NodeConfig";
import NodeIndexPage from "./NodeIndexPage";
import NodeTemplatePage from "./NodeTemplatePage";

const NODES_ANCESTOR_LABELS = ["Grammar"] as const;

const SUB_PAGE_LABELS: Record<string, string | undefined> = {
  [nodeConfigSegmentIds.index]: "Index",
  [nodeConfigSegmentIds.template]: "Template",
};

const GrammarNodesRoute = ({
  onloadArgs,
}: {
  onloadArgs: OnloadArgs;
}): JSX.Element => {
  const { segments, goToDepth } = useSettingsNav();
  const nodes = getDiscourseNodes().filter(excludeDefaultNodes);

  const [nodeTypeUid, subPage] = segments;
  const node = nodeTypeUid
    ? nodes.find((n) => n.type === nodeTypeUid)
    : undefined;

  // A deleted node type or stale deep link resolves to nothing; return to the list.
  const isStalePath = Boolean(nodeTypeUid) && !node;
  useEffect(() => {
    if (isStalePath) goToDepth(0);
  }, [isStalePath, goToDepth]);

  const resolveLabel = (segment: string, segmentIndex: number): string =>
    segmentIndex === 0
      ? (nodes.find((n) => n.type === segment)?.text ?? segment)
      : (SUB_PAGE_LABELS[segment] ?? segment);

  return (
    <div className="flex h-full flex-col">
      <SettingsPageHeader
        ancestorLabels={NODES_ANCESTOR_LABELS}
        rootLabel="Nodes"
        resolveLabel={resolveLabel}
      />
      {/* `-mx-1 px-1` widens the scroll box so the search flash is not clipped; content stays put. */}
      <div className="-mx-1 min-h-0 flex-auto overflow-y-auto px-1">
        {!node ? (
          <div className="p-1">
            <DiscourseNodeConfigPanel />
          </div>
        ) : subPage === nodeConfigSegmentIds.index ? (
          <NodeIndexPage node={node} onloadArgs={onloadArgs} />
        ) : subPage === nodeConfigSegmentIds.template ? (
          <NodeTemplatePage node={node} />
        ) : (
          <NodeConfig node={node} />
        )}
      </div>
    </div>
  );
};

export default GrammarNodesRoute;
import React from "react";
import { Button } from "@blueprintjs/core";
import { buildBreadcrumbTrail } from "~/components/settings/utils/settingsNavigation";
import { useSettingsNav } from "./SettingsNavContext";

/** `ancestorLabels` are static crumbs above the tab itself: shown in the trail, not navigable. */
const SettingsPageHeader = ({
  ancestorLabels,
  rootLabel,
  resolveLabel,
}: {
  ancestorLabels: readonly string[];
  rootLabel: string;
  resolveLabel: (segment: string, segmentIndex: number) => string;
}): JSX.Element | null => {
  const { path, depth, pop, goToDepth } = useSettingsNav();
  if (depth === 0) return null;

  // depth > 0, so the trail always has a root crumb plus at least one segment.
  const trail = buildBreadcrumbTrail({ path, rootLabel, resolveLabel });
  const current = trail[trail.length - 1];
  const parent = trail[trail.length - 2];

  return (
    // Shrinkable by default: without flex-shrink-0 the header squashes into the scrolling body.
    <div className="mb-5 block flex-shrink-0">
      <div className="mb-1 flex items-center gap-2 text-2xl font-semibold leading-tight">
        <Button
          minimal
          small
          icon="chevron-left"
          title={`Back to ${parent.label}`}
          aria-label={`Back to ${parent.label}`}
          onClick={pop}
        />
        {current.label}
      </div>
      <div className="text-sm leading-snug text-gray-500">
        {ancestorLabels.map((label) => (
          <span key={label}>{`${label} › `}</span>
        ))}
        {trail.map((crumb) => (
          <span key={crumb.depth}>
            {crumb.isCurrent ? (
              crumb.label
            ) : (
              <>
                <a
                  className="cursor-pointer"
                  onClick={() => goToDepth(crumb.depth)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ")
                      goToDepth(crumb.depth);
                  }}
                >
                  {crumb.label}
                </a>
                {" › "}
              </>
            )}
          </span>
        ))}
      </div>
    </div>
  );
};

export default SettingsPageHeader;
import { useEffect } from "react";
import { settingAnchorSelector } from "~/components/settings/utils/settingAnchor";

/** Roughly 500ms at 60fps. */
const MAX_LOOKUP_FRAMES = 30;
const FLASH_HOLD_MS = 600;
const FLASH_FADE_MS = 700;

/** `-mx-2 px-2` widens the highlight past the row's content without moving it. */
const FLASH_FRAME_CLASSES = [
  "-mx-2",
  "px-2",
  "rounded",
  "transition-colors",
  "duration-700",
];
const FLASH_FILL_CLASS = "bg-gray-100";

const flashTimeouts = new WeakMap<Element, number[]>();

/** Owns the flash independently of the effect: settling clears anchorId and re-runs the
 *  effect, whose cleanup would otherwise strip the classes before they are seen. */
const flashRow = (target: Element): void => {
  flashTimeouts.get(target)?.forEach((id) => window.clearTimeout(id));

  target.classList.add(...FLASH_FRAME_CLASSES, FLASH_FILL_CLASS);
  flashTimeouts.set(target, [
    // Dropping the fill while the transition class is still on fades it out.
    window.setTimeout(
      () => target.classList.remove(FLASH_FILL_CLASS),
      FLASH_HOLD_MS,
    ),
    window.setTimeout(() => {
      target.classList.remove(...FLASH_FRAME_CLASSES);
      flashTimeouts.delete(target);
    }, FLASH_HOLD_MS + FLASH_FADE_MS),
  ]);
};

/** The row is not in the DOM when the jump is dispatched — only the active panel renders,
 *  and a `Collapse` mounts later still — so a single lookup misses and this retries. */
export const useSettingAnchorScroll = ({
  anchorId,
  onSettled,
}: {
  anchorId: string | null;
  onSettled: () => void;
}): void => {
  useEffect(() => {
    if (!anchorId) return;
    let frame = 0;
    let rafId = 0;

    const look = () => {
      const target = document.querySelector(settingAnchorSelector(anchorId));
      if (target) {
        target.scrollIntoView({ block: "center", behavior: "smooth" });
        flashRow(target);
        onSettled();
        return;
      }
      if (frame++ >= MAX_LOOKUP_FRAMES) {
        onSettled();
        return;
      }
      rafId = requestAnimationFrame(look);
    };

    rafId = requestAnimationFrame(look);
    return () => cancelAnimationFrame(rafId);
  }, [anchorId, onSettled]);
};
